app.Services.GetRequiredService<Microsoft.Extensions.Options.IOptions<Microsoft.Extensions.ML.MLOptions>>()
    .Value.MLContext = new Microsoft.ML.MLContext(seed: 42);

app.MapControllers();
app.Run();

